        "DataExecucao" timestamp with time zone,
        "DataConclusao" timestamp with time zone,
        "TotalDestinatarios" integer NOT NULL,
        "TotalEnviados" integer NOT NULL,
        "TotalErros" integer NOT NULL,
        "Observacoes" character varying(500),
        "CriadoPor" character varying(100) NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL DEFAULT (NOW()),
        "AtualizadoEm" timestamp with time zone,
        "AtualizadoPor" character varying(100),
        CONSTRAINT "PK_Campanhas" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Campanhas_Farmacias_FarmaciaId" FOREIGN KEY ("FarmaciaId") REFERENCES "Farmacias" ("Id") ON DELETE CASCADE
