        "WhatsAppAccessToken" character varying(500) NOT NULL,
        "WhatsAppBusinessAccountId" character varying(100) NOT NULL,
        "ChaveWhatsApp" character varying(50) NOT NULL,
        "InstagramAccountId" character varying(100),
        "PageId" character varying(100),
        "InstagramAccessToken" character varying(500),
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone,
        CONSTRAINT "PK_FarmaciaIntegracoes" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_FarmaciaIntegracoes_Farmacias_FarmaciaId" FOREIGN KEY ("FarmaciaId") REFERENCES "Farmacias" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260414193512_AddFarmaciaIntegracoes') THEN
    INSERT INTO "FarmaciaIntegracoes"
        ("FarmaciaId", "WhatsAppPhoneNumberId", "WhatsAppAccessToken",
         "WhatsAppBusinessAccountId", "ChaveWhatsApp",
         "InstagramAccountId", "PageId", "InstagramAccessToken",
         "CreatedAt")
    SELECT
        "Id",
        COALESCE("WhatsAppPhoneNumberId", ''),
        COALESCE("WhatsAppAccessToken", ''),
        COALESCE("WhatsAppBusinessAccountId", ''),
        COALESCE(NULLIF("ChaveWhatsApp", ''), 'migrated-' || "Id"::text),
        "InstagramAccountId",
        "PageId",
        "InstagramAccessToken",
        NOW()
    FROM "Farmacias";
    END IF;
END $EF$;

